import React from 'react';
import { Link } from 'react-router-dom';
import { sanitizeHTML } from '../utils/security';

const PropertyCard = ({ property, isFavourite, onToggleFavourite }) => {
  const formatPrice = (price) => {
    return `£${price.toLocaleString()}`;
  };

  const getDateString = (added) => {
    return `${added.day} ${added.month} ${added.year}`;
  };

  return (
    <div className="property-card">
      <div className="property-image">
        <img 
          src={property.picture} 
          alt={property.type} 
          loading="lazy"
        />
        <button 
          className={`favourite-btn ${isFavourite ? 'active' : ''}`}
          onClick={() => onToggleFavourite(property.id)}
          aria-label={isFavourite ? "Remove from favourites" : "Add to favourites"}
        >
          {isFavourite ? '❤️' : '🤍'}
        </button>
        <div className="property-badge">
          {property.type}
        </div>
      </div>
      
      <div className="property-info">
        <h3 className="property-price">{formatPrice(property.price)}</h3>
        <p className="property-location">
          <span role="img" aria-label="location">📍</span> 
          {sanitizeHTML(property.location)}
        </p>
        
        <div className="property-details">
          <div className="detail">
            <span role="img" aria-label="bedrooms">🛏️</span>
            <span>{property.bedrooms} bed</span>
          </div>
          <div className="detail">
            <span role="img" aria-label="tenure">📄</span>
            <span>{property.tenure}</span>
          </div>
          <div className="detail">
            <span role="img" aria-label="date">📅</span>
            <span>{getDateString(property.added)}</span>
          </div>
        </div>
        
        <p className="property-description">
          {sanitizeHTML(property.description.substring(0, 120))}...
        </p>
        
        <Link to={`/property/${property.id}`} className="btn btn-view">
          View Details
        </Link>
      </div>
    </div>
  );
};

const PropertyList = ({ properties, favourites, onToggleFavourite }) => {
  if (properties.length === 0) {
    return (
      <div className="no-results">
        <h3>No properties found</h3>
        <p>Try adjusting your search criteria</p>
      </div>
    );
  }

  return (
    <div className="property-grid">
      {properties.map(property => (
        <PropertyCard
          key={property.id}
          property={property}
          isFavourite={favourites.includes(property.id)}
          onToggleFavourite={onToggleFavourite}
        />
      ))}
    </div>
  );
};

export default PropertyList;
